import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.CukOUUOK.js";const u=JSON.parse('{"title":"为什么判断\\"贵不贵\\"要看 PE 历史分位，而不是 52 周价格","description":"价格分位衡量的是别人过去一年愿意付多少钱，估值分位才更接近\\"现在值多少钱\\"。但估值分位同样有失效边界。","frontmatter":{"title":"为什么判断\\"贵不贵\\"要看 PE 历史分位，而不是 52 周价格","categories":"投资笔记","tags":["投资","方法论"],"description":"价格分位衡量的是别人过去一年愿意付多少钱，估值分位才更接近\\"现在值多少钱\\"。但估值分位同样有失效边界。","date":"2026-09-06T12:00:00.000Z"},"headers":[],"relativePath":"posts/2026-09-06-pe-percentile-vs-price-percentile.md","filePath":"posts/2026-09-06-pe-percentile-vs-price-percentile.md","lastUpdated":1789114868000}'),l={name:"posts/2026-09-06-pe-percentile-vs-price-percentile.md"};function i(n,e,s,p,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="为什么判断-贵不贵-要看-pe-历史分位-而不是-52-周价格" tabindex="-1">为什么判断&quot;贵不贵&quot;要看 PE 历史分位，而不是 52 周价格 <a class="header-anchor" href="#为什么判断-贵不贵-要看-pe-历史分位-而不是-52-周价格" aria-label="Permalink to &quot;为什么判断&quot;贵不贵&quot;要看 PE 历史分位，而不是 52 周价格&quot;">​</a></h1><h2 id="一个常见的错觉" tabindex="-1">一个常见的错觉 <a class="header-anchor" href="#一个常见的错觉" aria-label="Permalink to &quot;一个常见的错觉&quot;">​</a></h2><p>&quot;这只 ETF 现在处于 52 周价格的 85% 分位，太贵了，等回调再买。&quot;</p><p>这句话的问题在于：<strong>价格分位衡量的是相对过去一年别人愿意付多少钱，而不是相对这个资产现在值多少钱。</strong> 这两件事在趋势市里会严重背离。</p><p>举两个反例：</p><ul><li>一个宽基指数成分股盈利三年翻倍，指数涨了 80%。此时价格分位接近 100%，但 PE 可能比三年前还低——&quot;价格贵&quot;是错觉。</li><li>一个指数在盈利持续下滑的通道里阴跌，价格分位跌到 20%，看起来遍地黄金。但分母（盈利）掉得比价格更快，PE 反而创了新高——&quot;价格便宜&quot;是陷阱。</li></ul><p><strong>价格是分子，盈利是分母。只看分子不看分母，等于只看了半个估值。</strong></p><h2 id="pe-历史分位在测什么" tabindex="-1">PE 历史分位在测什么 <a class="header-anchor" href="#pe-历史分位在测什么" aria-label="Permalink to &quot;PE 历史分位在测什么&quot;">​</a></h2><p>PE 历史分位回答的问题是：<strong>当前的估值水平，在过去 N 年（通常取 10 年覆盖一个完整周期）里排在第几位。</strong></p><ul><li>分位 &lt; 20%：历史上只有 20% 的时间比现在便宜，属于低估区间</li><li>分位 20%–80%：估值中枢附近，无明显指示意义</li><li>分位 &gt; 80%：历史上只有 20% 的时间比现在贵，属于高估区间</li></ul><p>它的价值不在于&quot;预测涨跌&quot;，而在于<strong>给出一个概率上的赔率参考</strong>：低估区间买入，未来 3 年的期望收益率显著高于高估区间买入。这已经被大量的历史回测反复验证。</p><h2 id="三种必须知道的失效场景" tabindex="-1">三种必须知道的失效场景 <a class="header-anchor" href="#三种必须知道的失效场景" aria-label="Permalink to &quot;三种必须知道的失效场景&quot;">​</a></h2><p>估值分位不是万能的。以下三种情况下，PE 分位会给出方向上错误的信号：</p><h3 id="_1-周期股-低-pe-恰恰是最危险的时刻" tabindex="-1">1. 周期股：低 PE 恰恰是最危险的时刻 <a class="header-anchor" href="#_1-周期股-低-pe-恰恰是最危险的时刻" aria-label="Permalink to &quot;1. 周期股：低 PE 恰恰是最危险的时刻&quot;">​</a></h3><p>周期行业的盈利在周期顶部达到峰值，此时 PE 看起来极低（分位 5%），但接下来盈利可能腰斩，股价随之下杀。<strong>周期股的高 PE（盈利底部）往往是买点，低 PE（盈利顶部）往往是卖点</strong>，与直觉完全相反。</p><p>应对：周期行业用 <strong>PB 分位</strong> 或 <strong>席勒 PE（CAPE，取 10 年平均盈利平滑周期波动）</strong> 交叉验证。若 PE 分位与 PB 分位结论相反，以 PB 分位为准。</p><h3 id="_2-盈利为负-pe-失去数学意义" tabindex="-1">2. 盈利为负：PE 失去数学意义 <a class="header-anchor" href="#_2-盈利为负-pe-失去数学意义" aria-label="Permalink to &quot;2. 盈利为负：PE 失去数学意义&quot;">​</a></h3><p>分母为负时，PE 是个负数，既不能排序也不能比较分位。</p><p>应对：改用 PS（市销率）或 PB。宽基指数很少出现整体亏损，个股则很常见。</p><h3 id="_3-指数成分大幅变动-历史序列不可比" tabindex="-1">3. 指数成分大幅变动：历史序列不可比 <a class="header-anchor" href="#_3-指数成分大幅变动-历史序列不可比" aria-label="Permalink to &quot;3. 指数成分大幅变动：历史序列不可比&quot;">​</a></h3><p>如果一个指数的成分股在某一年做了大调整（比如行业主题指数大幅换仓），那么调整前后的 PE 序列在统计上不可比，分位数失真。</p><p>应对：优先采用指数公司官方公布的估值数据，或把观察窗口限制在成分稳定的时间段内。</p><h2 id="我的实际做法" tabindex="-1">我的实际做法 <a class="header-anchor" href="#我的实际做法" aria-label="Permalink to &quot;我的实际做法&quot;">​</a></h2><p>给自己的三条纪律，写下来是为了防止事后给自己找借口：</p><ol><li><strong>宽基指数</strong>：以 PE 历史分位为主判据，用 PB 分位与股债收益差（1/PE − 十年期国债收益率）做交叉验证。三者共振时置信度最高。</li><li><strong>价格分位只作为情绪的辅助读数</strong>，不作为买卖依据。它的作用是回答&quot;市场现在热不热&quot;，而不是&quot;这个资产便不便宜&quot;。</li><li><strong>场内品种必查溢价率</strong>。QDII 额度紧张时，场内 ETF 经常出现 5% 以上的溢价，此时买入等于开仓先亏掉溢价部分。这一点在境外仓位上踩过不止一次。</li></ol><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>价格分位告诉你市场情绪，估值分位告诉你赔率。做决策要用赔率，参考情绪，而不是反过来。</strong></p><blockquote><p>本文为个人投资方法的记录与复盘，不构成任何投资建议。</p></blockquote>',28)])])}const d=t(l,[["render",i]]);export{u as __pageData,d as default};
